const questions = [
  { q: 'Finance needs read-only visibility of every resource in one production resource group. What is the least-privileged assignment?', options: ['Owner at subscription', 'Reader at the resource group', 'Contributor at the resource group', 'Reader at management group'], answer: 1, why: 'Reader at the needed resource-group scope supplies visibility without write rights or an unnecessary wider scope.' },
  { q: 'A vendor’s service SAS must be invalidated before scheduled expiration if a contract ends. What supports that most directly?', options: ['A public container', 'A stored access policy referenced by a service SAS', 'A second storage account key', 'A lifecycle rule'], answer: 1, why: 'A stored access policy lets you alter or revoke a policy-backed service SAS without waiting for its original expiry.' },
  { q: 'A Windows workload requires a managed cloud file share mounted like a network share. Which service fits?', options: ['Azure Blob Storage', 'Azure Files', 'Azure Queue Storage', 'Azure Table Storage'], answer: 1, why: 'Azure Files is the managed file-share service. Blob Storage is object storage, not an SMB/NFS share.' },
  { q: 'A storage account must remain available through a zonal failure in its primary region. Which option is the direct match?', options: ['LRS', 'ZRS', 'GRS', 'RA-GRS'], answer: 1, why: 'ZRS synchronously replicates across availability zones in one region. Geo-redundancy answers a regional-disaster requirement instead.' },
  { q: 'A team needs a repeatable deployment definition that can be reviewed and redeployed with changed inputs. What should it use?', options: ['Bicep', 'Azure Advisor', 'Network Watcher', 'Storage Explorer'], answer: 0, why: 'Bicep declares Azure resources and desired configuration; parameters make deployments reusable.' },
  { q: 'A stateless API must scale a homogeneous group of virtual machines as demand rises. Which option is natural?', options: ['Availability set', 'Virtual Machine Scale Set', 'Recovery Services vault', 'Azure Bastion'], answer: 1, why: 'VM Scale Sets manage and scale a fleet of similar VMs. Availability sets distribute availability but are not fleet management.' },
  { q: 'A container image must be stored privately in Azure before it is run. Which service should host the image?', options: ['Azure Container Registry', 'Azure Container Instances', 'Azure App Service plan', 'Azure DNS'], answer: 0, why: 'Azure Container Registry stores and manages images. Container Instances runs a container; it is not the image registry.' },
  { q: 'A web team wants to validate a new build separately, then switch it into production with minimal release disruption. What App Service feature fits?', options: ['Availability zone', 'Deployment slot', 'Private endpoint', 'Recovery point'], answer: 1, why: 'Deployment slots provide separate app environments and support a swap workflow for staged releases.' },
  { q: 'A subnet must send traffic for an on-premises prefix through a virtual appliance. Which control changes the next hop?', options: ['Network security group', 'User-defined route', 'Application security group', 'Private DNS zone'], answer: 1, why: 'A route table with a user-defined route determines the next hop. An NSG filters; it does not steer traffic.' },
  { q: 'A VM cannot be reached after a security change. Before editing an NSG, what best shows the combined rules that apply?', options: ['Azure Advisor recommendation', 'Effective security rules', 'Cost analysis', 'A resource lock'], answer: 1, why: 'Effective security rules reveal rules applied through the NIC and subnet, letting you diagnose before adding another change.' },
  { q: 'Admins need browser-based RDP/SSH to VMs while avoiding public IPs on workload VMs. What is best?', options: ['Azure Bastion', 'Azure Load Balancer', 'NAT Gateway', 'Traffic Manager'], answer: 0, why: 'Azure Bastion provides managed portal connectivity without a public IP on every target VM.' },
  { q: 'A PaaS storage service must be accessed from a VNet through a private address. Which feature is required?', options: ['Service endpoint', 'Private endpoint', 'Public IP', 'NSG service tag'], answer: 1, why: 'A private endpoint creates a network interface with a private IP in the VNet for a supported PaaS resource.' },
  { q: 'An application distributes TCP traffic across healthy VMs and does not need HTTP path routing. What is best?', options: ['Azure Load Balancer', 'Application Gateway', 'Azure Front Door', 'Azure DNS'], answer: 0, why: 'Azure Load Balancer is a Layer 4 TCP/UDP distributor. Application Gateway adds Layer 7 web capability not required here.' },
  { q: 'An alert should fire when average CPU remains above a threshold for five minutes. Which signal should it evaluate?', options: ['Metric', 'Activity Log event', 'Azure Policy state', 'Resource lock'], answer: 0, why: 'CPU utilization is a numeric time-series metric, the direct input for a threshold alert.' },
  { q: 'You need to identify who changed a network security group rule yesterday. Which data source starts the investigation?', options: ['Activity Log', 'VM Insights', 'Blob versioning', 'Connection Monitor'], answer: 0, why: 'Activity Log records subscription-level management operations, including resource configuration changes.' },
  { q: 'A company wants replicated VM workloads in a second region for planned or unplanned DR failover. What is best?', options: ['Azure Backup', 'Azure Site Recovery', 'Soft delete', 'Azure Policy'], answer: 1, why: 'Site Recovery replicates workloads and orchestrates failover. Backup recovery points support restore, not live DR failover.' },
  { q: 'A subscription-level policy denies public IP resources. Where does it apply by inheritance?', options: ['Only the subscription object', 'Child resource groups and resources in that subscription', 'Only tagged resources', 'Only a selected VNet'], answer: 1, why: 'Assignments at subscription scope flow to child resource groups and resources unless an applicable exemption changes the result.' },
  { q: 'A user deleted a blob yesterday and overwrote a different blob last week. Which pair addresses both events?', options: ['Lifecycle and immutability', 'Soft delete and blob versioning', 'Access keys and SAS', 'Snapshots and a public container'], answer: 1, why: 'Soft delete retains deleted blobs during retention; versioning preserves earlier versions after overwrites.' },
];

