const flashcards = [
  { category: 'Prerequisites', front: 'Azure Resource Manager scope order', back: 'Tenant → management group → subscription → resource group → resource. Settings at a parent scope can apply to child scopes.', source: learn.prereq },
  { category: 'Prerequisites', front: 'Control plane vs data plane', back: 'Control-plane operations create or configure Azure resources through Resource Manager. Data-plane operations use the resource itself, such as reading a blob.', source: learn.prereq },
  { category: 'Prerequisites', front: 'ARM/Bicep parameters', back: 'Parameters accept values at deployment time so one declarative definition can be reused with different inputs.', source: learn.prereq },
  { category: 'Prerequisites', front: 'ARM/Bicep resources and outputs', back: 'Resources describe what Azure should create or update. Outputs expose values after deployment for a person, script, or another deployment.', source: learn.prereq },
  { category: 'Governance', front: 'Microsoft Entra ID', back: 'The cloud identity service that manages identities such as users, groups, applications, and service principals.', source: learn.governance },
  { category: 'Governance', front: 'RBAC vs Azure Policy', back: 'RBAC decides who can perform an action. Policy evaluates or enforces which resource configurations are allowed.', source: learn.governance },
  { category: 'Governance', front: 'Azure Policy initiative', back: 'A collection of related policy definitions that can be assigned together to evaluate or enforce a broader standard.', source: learn.governance },
  { category: 'Governance', front: 'Azure Policy: audit vs deny', back: 'Audit records noncompliance without blocking the request. Deny blocks a request that does not meet the assigned standard.', source: learn.governance },
  { category: 'Governance', front: 'Resource lock', back: 'CanNotDelete blocks deletion. ReadOnly also blocks management-plane changes. A lock does not grant access or block all data-plane activity.', source: learn.governance },
  { category: 'Governance', front: 'Tags', back: 'Key-value metadata used to organize and report on Azure resources. Tags support cost ownership and operations, but they do not grant access.', source: learn.governance },
  { category: 'Governance', front: 'Management group', back: 'A scope above subscriptions for applying governance, access, and compliance conditions across many subscriptions.', source: learn.governance },
  { category: 'Governance', front: 'Azure budget', back: 'A cost threshold with notifications. A budget warns about spending; it does not automatically stop resource usage.', source: learn.governance },
  { category: 'Storage', front: 'LRS / ZRS / GRS', back: 'LRS replicates in one datacenter. ZRS replicates across availability zones in one region. GRS also replicates asynchronously to a paired secondary region.', source: learn.storage },
  { category: 'Storage', front: 'RA-GRS / RA-GZRS', back: 'Read-access geo-redundant options allow read access to the secondary region in addition to geo-replication.', source: learn.storage },
  { category: 'Storage', front: 'Shared access signature (SAS)', back: 'A SAS delegates bounded Storage access. Restrict permissions, resource, protocol, IP when useful, and expiry time.', source: learn.storage },
  { category: 'Storage', front: 'Stored access policy', back: 'For a policy-backed service SAS, it provides a central way to change or revoke permissions or expiry without waiting for the original token to expire.', source: learn.storage },
  { category: 'Storage', front: 'Blob versioning vs soft delete', back: 'Versioning preserves earlier versions after overwrite. Soft delete retains deleted blobs or containers during a retention period.', source: learn.storage },
  { category: 'Storage', front: 'Azure Files vs Blob Storage', back: 'Azure Files provides managed SMB/NFS file shares. Blob Storage is object storage organized in containers.', source: learn.storage },
  { category: 'Storage', front: 'Storage account access keys', back: 'Account keys are powerful shared secrets. Prefer identity-based authorization where supported and avoid sharing account keys with users.', source: learn.storage },
  { category: 'Storage', front: 'Blob lifecycle management', back: 'Lifecycle rules automate tier movement or deletion based on age or conditions. They are cost-management rules, not a substitute for recovery protection.', source: learn.storage },
  { category: 'Networking', front: 'VNet and subnet', back: 'A VNet is a private address space. Subnets divide it into ranges for workloads and services; plan nonoverlapping room for growth.', source: learn.network },
  { category: 'Networking', front: 'NSG priority', back: 'NSG rules are evaluated by priority; lower numbers are processed first. Inbound and outbound rules are separate.', source: learn.network },
  { category: 'Networking', front: 'Effective security rules', back: 'The combined rules applied to a network interface and subnet. Inspect them before adding a new NSG rule.', source: learn.network },
  { category: 'Networking', front: 'Application security group (ASG)', back: 'A logical grouping of network interfaces that can be referenced in NSG rules, letting rules describe workload roles instead of individual IP addresses.', source: learn.network },
  { category: 'Networking', front: 'User-defined route (UDR)', back: 'A route-table entry that changes a subnet’s next hop. It steers traffic; it does not allow or deny traffic.', source: learn.network },
  { category: 'Networking', front: 'VNet peering', back: 'Private connectivity between VNets. Peering is not automatically transitive, so a third VNet does not gain connectivity simply because two peerings exist.', source: learn.network },
  { category: 'Networking', front: 'Service endpoint vs private endpoint', back: 'A service endpoint keeps the PaaS service public but extends VNet identity. A private endpoint gives the PaaS resource a private IP in your VNet.', source: learn.network },
  { category: 'Networking', front: 'Private DNS with private endpoints', back: 'The service name must resolve to the private endpoint’s private IP. A private DNS zone linked to the VNet is commonly required.', source: learn.network },
  { category: 'Networking', front: 'Azure Bastion', back: 'Managed portal-based SSH/RDP access to VMs without assigning public IP addresses to each workload VM.', source: learn.network },
  { category: 'Networking', front: 'Azure Load Balancer', back: 'A Layer 4 service that distributes TCP/UDP traffic across healthy backend instances using a frontend, rule, probe, and backend pool.', source: learn.network },
  { category: 'Networking', front: 'Application Gateway', back: 'A Layer 7 HTTP/S load-balancing service with web-aware routing and optional web application firewall capabilities.', source: learn.network },
  { category: 'Networking', front: 'Network Watcher', back: 'Azure network diagnostic and monitoring tools used to collect evidence about connectivity, routes, and security behavior.', source: learn.network },
  { category: 'Compute', front: 'Virtual machine', back: 'Choose a VM when the workload needs operating-system control, custom software, or a server-style lifecycle.', source: learn.compute },
  { category: 'Compute', front: 'Managed disks', back: 'Azure-managed block storage attached to VMs. Disk type, size, performance, encryption, and availability requirements are separate design choices.', source: learn.compute },
  { category: 'Compute', front: 'Availability set vs availability zone', back: 'An availability set spreads VMs across fault and update domains. Availability zones use distinct datacenters within an Azure region.', source: learn.compute },
  { category: 'Compute', front: 'Virtual Machine Scale Sets', back: 'A managed, scalable group of homogeneous VMs. Use it for a fleet rather than a one-off VM.', source: learn.compute },
  { category: 'Compute', front: 'Azure Container Registry', back: 'A private registry for storing and managing container images. It stores images; it does not run them.', source: learn.compute },
  { category: 'Compute', front: 'Azure Container Instances', back: 'A fast way to run a container without managing VMs or a full orchestrator. It fits isolated, short-lived, or straightforward container workloads.', source: learn.compute },
  { category: 'Compute', front: 'Azure Container Apps', back: 'A managed platform for containerized apps with application-oriented scaling and deployment capabilities.', source: learn.compute },
  { category: 'Compute', front: 'App Service plan', back: 'The compute capacity and pricing boundary that hosts one or more App Service apps. Scaling the plan affects its apps.', source: learn.compute },
  { category: 'Compute', front: 'App Service deployment slot', back: 'A separate environment for an App Service app. Slots let you validate a version and then swap it into production.', source: learn.compute },
  { category: 'Monitor & recovery', front: 'Metric vs log vs Activity Log', back: 'Metrics are numeric time series. Logs are rich records queried with KQL. Activity Log records subscription-level management operations.', source: learn.monitor },
  { category: 'Monitor & recovery', front: 'Alert rule / action group / processing rule', back: 'An alert rule evaluates a signal. An action group delivers notification. A processing rule changes notification behavior at scale.', source: learn.monitor },
  { category: 'Monitor & recovery', front: 'Azure Monitor Insights', back: 'Curated monitoring experiences for supported resource types that help interpret health, performance, and dependencies.', source: learn.monitor },
  { category: 'Monitor & recovery', front: 'Azure Backup', back: 'Creates recovery points that let you restore supported data and workloads. Validate the design with a restore test.', source: learn.monitor },
  { category: 'Monitor & recovery', front: 'Azure Site Recovery', back: 'Replicates workloads for disaster recovery and supports planned or unplanned failover to a secondary region.', source: learn.monitor },
  { category: 'Monitor & recovery', front: 'Recovery point objective (RPO)', back: 'The maximum acceptable amount of data loss measured in time. It helps define how frequently protection or replication must occur.', source: learn.monitor },
];

